class PayrollAccount {private double basicSalary,bonus;PayrollAccount(double salary){if(salary<0){System.out.println("Warning: negative salary replaced with 0");basicSalary=0;}else basicSalary=salary;}void creditBonus(double amount){if(amount<=0)System.out.println("Invalid bonus amount");else{bonus+=amount;System.out.println("Bonus credited: Rs "+amount);}}void deductTax(double percent){if(percent<0||percent>100)System.out.println("Invalid tax percentage");else{basicSalary-=basicSalary*percent/100;System.out.println("Tax deducted: "+percent+"%");}}double getNetSalary(){return basicSalary+bonus;}}
public class PayrollSalaryManagement {public static void main(String[] args){PayrollAccount p=new PayrollAccount(50000);p.creditBonus(5000);p.deductTax(10);System.out.println("Net salary: Rs "+p.getNetSalary());}}
